// The account-session handlers (l6-accounts 7.2): POST /auth/login mints a
// session token over identity.MintSession — the ONLY argon2id password check,
// whose uniform ErrAuth folds wrong password, unknown user, and disabled user
// into one 401 shape (D6: no account enumeration, dummy-hash burn on unknown
// users happens inside MintSession). POST /auth/logout deletes ONLY the
// presented session row over identity.RevokeSession. Sessions are header
// bearer credentials (kind='session', SHA-256 at rest) — never cookies.

// loginRequest is the body of POST /api/v1/auth/login.
type loginRequest struct {
	Username string `json:"username"`
	Password string `json:"password"`
}

// loginResponse is the body of a successful POST /api/v1/auth/login: the RAW
// session token (design wire contract: `{username, password}` → `{token}`).
// It crosses the wire exactly once — the SPA stores it as the credential it
// later presents as `Authorization: Bearer <token>`; only its SHA-256 lives
// at rest (INV3, the pairing-token discipline).
type loginResponse struct {
	Token string `json:"token"`
}

// loginLimitMax / loginWindow are the login fixed window (D6): at most
// loginLimitMax login attempts per loginWindow per (IP, username) key —
// the pairing limiter's shape (internal/pairing ipWindow/allow) re-derived
// in-process, keyed on the TUPLE (the pairing limiter is per-IP only and
// lives behind the pairing service, which is not this endpoint's domain).
// The excess is 429'd.
const (
	loginLimitMax = 5
	loginWindow   = 5 * time.Minute
	// loginMaxKeys bounds the key set before the amortized prune kicks in
	// (username-spray growth — the beaconLimiter's beaconMaxKeys rule).
	loginMaxKeys = 1024
)

// loginLimiter is the in-process fixed-window counter behind the login 429.
// Plain local state on the app (never a Deps closure — no domain behind it,
// INV1 pure delegation), deliberately NOT store-backed: the limit bounds
// brute-force pressure, so process restart resets it and that is fine.
// Keyed (client IP, username): a DIFFERENT username from the same IP is a
// different bucket — one locked-out account is not a denial of service for
// the household's other users; per-IP bounds pairing, per-account bounds
// guessing (D6). NAT-sharing a bucket is accepted, exactly like the beacon
// limiter's posture.
type loginLimiter struct {
	mu   sync.Mutex
	hits map[string]*loginCounter
}

// loginCounter is one key's fixed window: attempts within
// [start, start+loginWindow).
type loginCounter struct {
	start time.Time
	n     int
}

// newLoginLimiter builds the limiter over the package constants.
func newLoginLimiter() *loginLimiter {
	return &loginLimiter{hits: map[string]*loginCounter{}}
}

// allow records one attempt for key and reports whether it is still within
// the loginLimitMax budget. Expired windows are reset in place; the key set
// is pruned only when it has grown past loginMaxKeys (amortized O(1)).
func (l *loginLimiter) allow(key string) bool {
	l.mu.Lock()
	defer l.mu.Unlock()
	now := time.Now()
	if len(l.hits) > loginMaxKeys {
		for k, w := range l.hits {
			if now.Sub(w.start) >= loginWindow {
				delete(l.hits, k)
			}
		}
	}
	w := l.hits[key]
	if w == nil || now.Sub(w.start) >= loginWindow {
		w = &loginCounter{start: now}
		l.hits[key] = w
	}
	if w.n >= loginLimitMax {
		return false
	}
	w.n++
	return true
}

// identityService guards the nil-service convention: Deps.Identity nil →
// 503, the pairingService precedent (a nil field means the endpoint is not
// wired — zero-user legacy deployments that never construct a real Identity).
func (a *app) identityService() (*identity.Service, bool) {
	if a.deps.Identity == nil {
		return nil, false
	}
	return a.deps.Identity, true
}

// login: POST /api/v1/auth/login — verifies the credential and mints a
// session token (unauthenticated: this is how a caller GETS a credential).
// The body is bound BEFORE limiting because the limiter's key needs the
// username; the (IP, username) key is then checked before any identity work.
// MintSession owns the password gate: its ErrAuth is the uniform refusal —
// the 401 body is byte-identical for wrong password, unknown user, and
// disabled user, and no handler-side distinction exists.
//
// @Summary     Log in and mint a session token
// @Tags        auth
// @ID          auth-login
// @Router      /auth/login [post]
// @Param       body body loginRequest true "username and password"
// @Success     200 {object} loginResponse
// @Failure     400 {object} errorBody
// @Failure     401 {object} errorBody "invalid credentials — uniform, no enumeration"
// @Failure     429 {object} errorBody "per-(IP, username) rate limit exceeded"
// @Failure     500 {object} errorBody
// @Failure     503 {object} errorBody
func (a *app) login(w http.ResponseWriter, r *http.Request) {
	idsvc, ok := a.identityService()
	if !ok {
		writeError(w, http.StatusServiceUnavailable, "unavailable", "auth endpoint disabled", false)
		return
	}
	var req loginRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil || strings.TrimSpace(req.Username) == "" {
		writeError(w, http.StatusBadRequest, "bad_request", "malformed JSON body", false)
		return
	}
	if !a.logins.allow(clientIP(r) + "\x00" + req.Username) {
		writeError(w, http.StatusTooManyRequests, "rate_limited",
			"too many login attempts for this account; retry later", false)
		return
	}
	sess, err := idsvc.MintSession(r.Context(), req.Username, req.Password)
	if err != nil {
		if errors.Is(err, identity.ErrAuth) {
			writeError(w, http.StatusUnauthorized, "unauthenticated", "invalid credentials", false)
			return
		}
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
		return
	}
	writeJSON(w, http.StatusOK, loginResponse{Token: sess.Token})
}

// logout: POST /api/v1/auth/logout — deletes ONLY the presented session row
// (authenticated: the bearer IS the capability). The presented token is
// re-read from the Authorization header — the middleware records the
// Principal on the context but not the raw credential, and re-reading the
// header is the pattern that keeps the secret out of context state
// (the beacon limiter's documented posture). RevokeSession's kind guard
// keeps device rows untouchable, so a device bearer or the env admin token
// has no session row to delete and the refusal is the uniform 401 — there
// is nothing authenticated-as-a-session about such a call.
//
// @Summary     Log out by deleting the presented session
// @Tags        auth
// @ID          auth-logout
// @Router      /auth/logout [post]
// @Success     204 "session deleted"
// @Failure     401 {object} errorBody "no session row behind the presented credential"
// @Failure     500 {object} errorBody
// @Failure     503 {object} errorBody
func (a *app) logout(w http.ResponseWriter, r *http.Request) {
	idsvc, ok := a.identityService()
	if !ok {
		writeError(w, http.StatusServiceUnavailable, "unavailable", "auth endpoint disabled", false)
		return
	}
	creds := bearerCredentials(r.Header.Get("Authorization"))
	if err := idsvc.RevokeSession(r.Context(), creds); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			writeError(w, http.StatusUnauthorized, "unauthenticated", "invalid credentials", false)
			return
		}
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}
